patch:
@@ -7,20 +7,6 @@ resource "azurerm_resource_group" "workout" {
   location = var.location
 }

-# ============================================================================
-# Shared Infrastructure (Remote State)
-# ============================================================================
-
-data "terraform_remote_state" "infra" {
-  backend = "azurerm"
-  config = {
-    resource_group_name  = "infra"
-    storage_account_name = "tfstate6792"
-    container_name       = "tfstate"
-    key                  = "infra.tfstate"
-    use_oidc             = true
-  }
-}

 # ============================================================================
 # Note: User/developer role assignments for Cosmos DB should be managed
@@ -46,12 +32,12 @@ output "static_web_app_default_hostname" {


 output "cosmos_db_endpoint" {
-  value       = data.terraform_remote_state.infra.outputs.cosmos_db_endpoint
+  value       = var.cosmos_db_endpoint
   description = "Cosmos DB account endpoint"
 }

 output "cosmos_db_name" {
-  value       = data.terraform_remote_state.infra.outputs.cosmos_db_account_name
+  value       = var.cosmos_db_account_name
   description = "Cosmos DB account name"
 }

@@ -1,47 +1,20 @@
 terraform {
   required_version = ">= 1.6.0"
-
   required_providers {
     azurerm = {
       source  = "hashicorp/azurerm"
       version = "~> 4.0"
     }
   }
-
-  backend "azurerm" {
-    resource_group_name  = "infra"
-    storage_account_name = "tfstate6792"
-    container_name       = "tfstate"
-    key                  = "kill-me.tfstate"
-    use_oidc             = true
-  }
 }

 provider "azurerm" {
   features {}
   use_oidc = true # Enable OIDC authentication
 }

-
-provider "infisical" {
-  host = "https://app.infisical.com"
-  auth = {
-    oidc = {
-      identity_id                     = "474b7b4f-9205-48f6-8ae1-2f4f2a248af1"
-      token_environment_variable_name = "GITHUB_OIDC_TOKEN" 
-    }
-  }
-}
-
-ephemeral "infisical_secret" "auth0_secret" {
-  name         = "auth0"
-  env_slug     = "prod"
-  folder_path  = "/"
-  workspace_id = "a5846fc0-c6e3-4a47-9deb-b3c6e2da9240"
-}
-
 provider "auth0" {
   domain        = "dev-gtdi5x5p0nmticqd.us.auth0.com"
   client_id     = "7qsN7zrBAh7TwhjEUcgtU46yOSs9TXbg"
-  client_secret = ephemeral.infisical_secret.auth0_secret.value
+  client_secret = var.auth0_client_secret
 }

@@ -7,3 +7,77 @@ variable "location" {
   type        = string
   default     = "westus2"
 }
+
+variable "auth0_client_secret" {
+  type      = string
+  sensitive = true
+}
+
+# ============================================================================
+# Shared Infrastructure Variables
+# ============================================================================
+
+variable "resource_group_name" {
+  description = "Name of the shared resource group"
+  type        = string
+}
+
+variable "resource_group_location" {
+  description = "Location of the shared resource group"
+  type        = string
+}
+
+variable "resource_group_id" {
+  description = "ID of the shared resource group"
+  type        = string
+}
+
+variable "dns_zone_name" {
+  description = "Name of the DNS zone"
+  type        = string
+}
+
+variable "dns_zone_id" {
+  description = "ID of the DNS zone"
+  type        = string
+}
+
+variable "dns_zone_nameservers" {
+  description = "Nameservers for the DNS zone"
+  type        = string
+}
+
+variable "container_app_environment_name" {
+  description = "Name of the Container App Environment"
+  type        = string
+}
+
+variable "container_app_environment_id" {
+  description = "ID of the Container App Environment"
+  type        = string
+}
+
+variable "cosmos_db_account_name" {
+  description = "Name of the Cosmos DB account"
+  type        = string
+}
+
+variable "cosmos_db_account_id" {
+  description = "ID of the Cosmos DB account"
+  type        = string
+}
+
+variable "cosmos_db_endpoint" {
+  description = "Endpoint URL of the Cosmos DB account"
+  type        = string
+}
+
+variable "azure_subscription_id" {
+  description = "Azure subscription ID"
+  type        = string
+}
+
+variable "azure_tenant_id" {
+  description = "Azure tenant ID"
+  type        = string
+}
